import com.google.gson.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.commons.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import net.farmingtales.ftboss.boss.ai.NativeManorDamageBridgeInstaller;
import net.farmingtales.ftboss.boss.ai.NativeManorMixinPlugin;
public final class ManorYouziOriginalSummonComposerV1 {
    private static final String BOSS="net/farmingtales/ftboss/entity/EasterBossEntity";
    private static final List<String> HELPERS=List.of("net/farmingtales/ftboss/youzi/YouziSummonScaling","net/farmingtales/ftboss/util/YouziSummonRules");
    private static final Set<String> SELECTED=Set.of("youziAddHit","summonMiniClones","supportSparrow");
    private static int checks,linkageChecks;
    private static final Map<String,ClassNode> hierarchy=new HashMap<>();
    private static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static ClassNode read(byte[] payload){ClassNode node=new ClassNode();new ClassReader(payload).accept(node,ClassReader.EXPAND_FRAMES);return node;}
    private static byte[] bytes(ClassNode node){ClassWriter writer=new ClassWriter(0);node.accept(writer);return writer.toByteArray();}
    private static ClassNode read(ZipFile jar,String name)throws Exception{var entry=jar.getEntry(name+".class");require(entry!=null,"Original entry exists "+name);return read(jar.getInputStream(entry).readAllBytes());}
    private static String graph(MethodNode method){return NativeManorDamageBridgeInstaller.graph(method);}
    private static MethodNode method(ClassNode node,String name){List<MethodNode> found=node.methods.stream().filter(value->value.name.equals(name)).toList();require(found.size()==1,"Unique selected method "+name);return found.getFirst();}
    private static Map<String,String> graphs(ClassNode node){Map<String,String> result=new LinkedHashMap<>();for(MethodNode method:node.methods)require(result.put(method.name+method.desc,graph(method))==null,"Unique method signature");return result;}
    private static String header(ClassNode node){return node.version+"|"+node.access+"|"+node.name+"|"+node.signature+"|"+node.superName+"|"+node.interfaces+"|"+node.fields.stream().map(field->field.access+":"+field.name+":"+field.desc+":"+field.signature+":"+field.value).toList();}
    private static ClassNode mapped(ClassNode original,Remapper mapper){ClassNode result=new ClassNode();original.accept(new ClassRemapper(result,mapper));return result;}
    private static int adapt(MethodNode method,boolean reverse){int count=0;String attribute="Lnet/minecraft/world/entity/ai/attributes/Attribute;",effect="Lnet/minecraft/world/effect/MobEffect;",holder="Lnet/minecraft/core/Holder;";for(AbstractInsnNode instruction:method.instructions){if(instruction instanceof FieldInsnNode field&&(field.owner.equals("net/minecraft/world/entity/ai/attributes/Attributes")||field.owner.equals("net/minecraft/world/effect/MobEffects"))){String old=field.owner.endsWith("Attributes")?attribute:effect;String from=reverse?holder:old,to=reverse?old:holder;require(field.desc.equals(from),"Exact original Holder field adapter "+field.name);field.desc=to;count++;}if(instruction instanceof MethodInsnNode call){String old=null;if(call.name.equals("getAttribute")||call.name.equals("getAttributeValue"))old=attribute;if(call.owner.equals("net/minecraft/world/effect/MobEffectInstance")&&call.name.equals("<init>"))old=effect;if(old!=null){String from=reverse?holder:old,to=reverse?old:holder;require(call.desc.contains(from),"Exact original Holder argument adapter "+call.name);call.desc=call.desc.replace(from,to);count++;}}}return count;}
    private static ClassNode lookup(String name)throws Exception{if(hierarchy.containsKey(name))return hierarchy.get(name);try(InputStream input=ClassLoader.getSystemResourceAsStream(name+".class")){require(input!=null,"Linkage owner exists "+name);ClassNode node=read(input.readAllBytes());hierarchy.put(name,node);return node;}}
    private static boolean member(String owner,String name,String desc,boolean field,Set<String> visited)throws Exception{if(!visited.add(owner))return false;ClassNode node=lookup(owner);if(field?node.fields.stream().anyMatch(value->value.name.equals(name)&&value.desc.equals(desc)):node.methods.stream().anyMatch(value->value.name.equals(name)&&value.desc.equals(desc)))return true;if(name.equals("<init>"))return false;if(node.superName!=null&&member(node.superName,name,desc,field,visited))return true;for(String parent:node.interfaces)if(member(parent,name,desc,field,visited))return true;return false;}
    private static void linkage(ClassNode node,MethodNode method)throws Exception{new Analyzer<BasicValue>(new BasicVerifier()).analyze(node.name,method);for(AbstractInsnNode instruction:method.instructions){if(instruction instanceof MethodInsnNode call){require(member(call.owner,call.name,call.desc,false,new HashSet<>()),"Method resolves "+call.owner+"."+call.name+call.desc);linkageChecks++;}if(instruction instanceof FieldInsnNode field){require(member(field.owner,field.name,field.desc,true,new HashSet<>()),"Field resolves "+field.owner+"."+field.name+field.desc);linkageChecks++;}}}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[3]);JsonObject mapping=JsonParser.parseString(Files.readString(Path.of(args[2]))).getAsJsonObject(),members=mapping.getAsJsonObject("memberNames"),types=mapping.getAsJsonObject("classNames");
        Remapper mapper=new Remapper(){public String map(String name){if(types.has(name))return types.get(name).getAsString();if(name.startsWith("net/minecraftforge/eventbus/api/"))return name.replace("net/minecraftforge/eventbus/api/","net/neoforged/bus/api/");if(name.startsWith("net/minecraftforge/fml/"))return name.replace("net/minecraftforge/fml/","net/neoforged/fml/");return name.replace("net/minecraftforge/","net/neoforged/neoforge/");}public String mapMethodName(String owner,String name,String descriptor){return members.has(name)?members.get(name).getAsString():name;}public String mapFieldName(String owner,String name,String descriptor){return members.has(name)?members.get(name).getAsString():name;}};
        JsonArray changes=new JsonArray(),helpers=new JsonArray();int adaptations=0;ClassNode baseline,patched;
        try(ZipFile original=new ZipFile(args[0]);ZipFile candidate=new ZipFile(args[1])){
            baseline=read(candidate,BOSS);patched=read(candidate,BOSS);ClassNode source=mapped(read(original,BOSS),mapper);
            for(String name:SELECTED){MethodNode expected=method(source,name),old=method(patched,name);String originalGraph=graph(expected);int adapterCount=adapt(expected,false);adaptations+=adapterCount;ClassNode temporary=new ClassNode();temporary.methods.add(expected);ClassNode reversed=read(bytes(source));MethodNode reverseMethod=method(reversed,name);require(adapt(reverseMethod,true)==adapterCount,"Exact reverse API adapter count "+name);require(graph(reverseMethod).equals(originalGraph),"Reversed adapters restore whole original graph "+name);require(expected.desc.equals(old.desc),"Existing selected signature unchanged");patched.methods.set(patched.methods.indexOf(old),expected);JsonObject row=new JsonObject();row.addProperty("method",name);row.addProperty("mappedOriginalGraph",originalGraph);row.addProperty("adaptedGraph",graph(expected));row.addProperty("apiAdapters",adapterCount);changes.add(row);}
            require(adaptations==4,"Only four original Attribute/MobEffect Holder API adaptations");require(header(baseline).equals(header(patched)),"Existing Boss class/field header unchanged");Map<String,String> before=graphs(baseline),after=graphs(patched);require(before.keySet().equals(after.keySet()),"Existing Boss method set unchanged");for(MethodNode value:baseline.methods)require(SELECTED.contains(value.name)?!before.get(value.name+value.desc).equals(after.get(value.name+value.desc)):before.get(value.name+value.desc).equals(after.get(value.name+value.desc)),"Only three original Boss methods changed: "+value.name);
            hierarchy.put(BOSS,patched);
            for(String name:HELPERS){require(candidate.getEntry(name+".class")==null,"New helper absent from baseline "+name);ClassNode helper=mapped(read(original,name),mapper);hierarchy.put(name,helper);byte[] payload=bytes(helper);ClassNode roundtrip=read(payload);require(header(helper).equals(header(roundtrip))&&graphs(helper).equals(graphs(roundtrip)),"Full mapped original helper roundtrip "+name);Path target=out.resolve(name+".class");Files.createDirectories(target.getParent());Files.write(target,payload);JsonObject row=new JsonObject();row.addProperty("class",name);row.addProperty("methods",helper.methods.size());row.addProperty("originalAllMethodsExactAfterOfficialMappings",true);helpers.add(row);}
        }
        for(String name:HELPERS)for(MethodNode value:hierarchy.get(name).methods)linkage(hierarchy.get(name),value);for(String name:SELECTED)linkage(patched,method(patched,name));
        byte[] payload=bytes(patched);ClassNode roundtrip=read(payload);require(graphs(roundtrip).equals(graphs(patched)),"All raw Boss methods roundtrip unchanged");Files.write(out.resolve("EasterBossEntity.class"),payload);
        ClassNode effectiveBefore=read(bytes(baseline)),effectiveAfter=read(payload);new NativeManorMixinPlugin().postApply(BOSS.replace('/','.'),effectiveBefore,"net.farmingtales.ftboss.mixin.NativeManorRaidMixin",null);new NativeManorMixinPlugin().postApply(BOSS.replace('/','.'),effectiveAfter,"net.farmingtales.ftboss.mixin.NativeManorRaidMixin",null);require(effectiveAfter.methods.size()==342&&effectiveBefore.methods.size()==342,"All 342 effective methods retained");Map<String,String> effectiveOld=graphs(effectiveBefore);for(MethodNode value:effectiveAfter.methods)require(SELECTED.contains(value.name)?graph(value).equals(graph(method(patched,value.name))):graph(value).equals(effectiveOld.get(value.name+value.desc)),"Only three effective methods differ "+value.name);require(graph(method(effectiveAfter,"hurt")).equals("7b5cc70744f2dea2e8287d8f575fe592c20e3cc6446c75e5fe60da93b63fbcb6"),"Complete original hurt retained");Files.write(out.resolve("simulated-after.class"),bytes(effectiveAfter));
        MethodNode wrong=method(read(payload),"summonMiniClones");MethodInsnNode scaling=Arrays.stream(wrong.instructions.toArray()).filter(value->value instanceof MethodInsnNode call&&call.name.equals("cap")).map(value->(MethodInsnNode)value).findFirst().orElseThrow();scaling.name="count";require(!graph(wrong).equals(graph(method(patched,"summonMiniClones"))),"Negative catches wrong multiplayer cap");MethodNode missing=method(read(payload),"youziAddHit");MethodInsnNode resonance=Arrays.stream(missing.instructions.toArray()).filter(value->value instanceof MethodInsnNode call&&call.name.equals("resonance")).map(value->(MethodInsnNode)value).findFirst().orElseThrow();missing.instructions.remove(resonance);require(!graph(missing).equals(graph(method(patched,"youziAddHit"))),"Negative catches omitted resonance hook");require(!member(BOSS,"summonMiniClones","()V",false,new HashSet<>()),"Negative rejects bad linkage descriptor");
        JsonObject receipt=new JsonObject();receipt.addProperty("checks",checks);receipt.addProperty("linkageReferences",linkageChecks);receipt.addProperty("negativeControls",3);receipt.addProperty("effectiveMethods",342);receipt.addProperty("unchangedOtherEffectiveMethods",339);receipt.addProperty("apiAdapters",adaptations);receipt.add("restoredMethods",changes);receipt.add("addedOriginalHelpers",helpers);receipt.addProperty("wholeOriginalHurtRetained",true);receipt.addProperty("fullManagedSparrowMultiplayerRestored",false);receipt.addProperty("nativeGameplayAccepted",false);receipt.addProperty("installable",false);Files.writeString(out.resolve("composition-proof.json"),new GsonBuilder().setPrettyPrinting().create().toJson(receipt));System.out.println("checks="+checks+";linkageReferences="+linkageChecks+";restoredMethods=3;helpers=2;negativeControls=3;wholeOriginalHurtRetained=true;");
    }
}
